from fastapi.testclient import TestClient
from app.main import app

def player_headers(client:TestClient)->dict[str,str]:
    login=client.post('/api/v1/auth/login',json={'identifier':'player@sbppadel.local','password':'PadelDemo2026!'});assert login.status_code==200;return {'Authorization':f"Bearer {login.json()['access_token']}"}
def test_confirm_reschedule_cancel_refund_lifecycle():
    with TestClient(app) as client:
        headers=player_headers(client);venue=next(v for v in client.get('/api/v1/venues').json() if v['name']=='Nishtar Park Sports Complex');detail=client.get(f"/api/v1/venues/{venue['id']}").json();court=next(c for c in detail['courts'] if c['code']=='04');policy=client.get('/api/v1/policies/active').json();original_date='2026-12-10';new_date='2026-12-11';start='14:00';created=client.post('/api/v1/bookings',headers=headers,json={'venue_id':venue['id'],'court_id':court['id'],'booking_date':original_date,'slots':[{'start_time':start}],'policy_version_id':policy['id'],'policy_accepted':True});assert created.status_code==200;booking=created.json();initiated=client.post('/api/v1/payments/initiate',headers=headers,json={'booking_id':booking['id'],'method':'wallet'});payment_id=initiated.json()['payment_id'];confirmed=client.post(f'/api/v1/payments/{payment_id}/simulate-success',headers=headers);assert confirmed.json()['booking_status']=='confirmed';moved=client.post(f"/api/v1/bookings/{booking['id']}/reschedule",headers=headers,json={'booking_date':new_date,'slots':[{'start_time':start}]});assert moved.status_code==200;assert moved.json()['status']=='rescheduled';detail_b=client.get(f"/api/v1/bookings/{booking['id']}",headers=headers).json();assert detail_b['date']==new_date;old=client.get(f"/api/v1/venues/{venue['id']}/availability?date={original_date}").json();old_c=next(r for r in old['courts'] if r['court_id']==court['id']);assert next(r for r in old_c['slots'] if r['start_time']==start)['available'] is True;new=client.get(f"/api/v1/venues/{venue['id']}/availability?date={new_date}").json();new_c=next(r for r in new['courts'] if r['court_id']==court['id']);assert next(r for r in new_c['slots'] if r['start_time']==start)['available'] is False;cancelled=client.post(f"/api/v1/bookings/{booking['id']}/cancel",headers=headers,json={'reason':'Player lifecycle QA'});assert cancelled.status_code==200;assert cancelled.json()['refund_required'] is True;refunded=client.post(f'/api/v1/payments/{payment_id}/refund',headers=headers,json={'reason':'Player lifecycle QA'});assert refunded.status_code==200;history=client.get('/api/v1/payments/me',headers=headers).json();payment=next(r for r in history if r['id']==payment_id);assert payment['refund']['status']=='requested';kinds={r['kind'] for r in client.get('/api/v1/notifications/me',headers=headers).json() if r['payload'].get('booking_id')==booking['id']};assert {'booking_confirmed','booking_rescheduled','booking_cancelled','refund_requested'}.issubset(kinds)
